using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    if (n > m) swap(n, m);
    int result;
    if (n == 1) {
        result = n * m - min(m % 6, 6 - m % 6);
    } else if (n == 2) {
        if (m == 2) result = n * m - 4;
        else if (m == 3) result = n * m - 2;
        else if (m == 7) result = n * m - 2;
        else result = n * m;
    } else {
        result = n * m - ((n & 1) * (m & 1));
    }
    cout << result << "\n";
    return 0;
}
